package android.view; public class Window { final ViewGroup root; final WindowManager.LayoutParams attrs=new WindowManager.LayoutParams(); public Window(android.content.Context c){root=new ViewGroup(c);} public View getDecorView(){return root;} public WindowManager.LayoutParams getAttributes(){return attrs;} public void setAttributes(WindowManager.LayoutParams p){attrs.screenBrightness=p.screenBrightness;} }
